describe('Internet Connection Drop - Friendly Message Display', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
  });

  it('should display friendly offline message when internet connection drops', () => {
    cy.intercept('GET', '**/*', { forceNetworkError: true }).as('networkError');

    cy.window().then((win) => {
      win.dispatchEvent(new Event('offline'));
    });

    cy.get('[data-testid="offline-message"]', { timeout: 5000 }).should('be.visible');
    cy.get('[data-testid="offline-message"]').should('contain', 'Connection Lost');
    cy.get('[data-testid="offline-message"]').should('contain', 'Please check your internet connection');
  });

  it('should display offline message with retry button and handle reconnection', () => {
    cy.window().then((win) => {
      win.dispatchEvent(new Event('offline'));
    });

    cy.get('[data-testid="offline-message"]', { timeout: 5000 }).should('be.visible');
    cy.get('[data-testid="retry-button"]').should('exist').and('be.enabled');
    cy.get('[data-testid="retry-button"]').should('contain', 'Retry');

    cy.window().then((win) => {
      win.dispatchEvent(new Event('online'));
    });

    cy.get('[data-testid="offline-message"]', { timeout: 5000 }).should('not.be.visible');
  });

  it('should maintain offline state across page navigation', () => {
    cy.window().then((win) => {
      win.dispatchEvent(new Event('offline'));
    });

    cy.get('[data-testid="offline-message"]').should('be.visible');

    cy.visit('http://localhost:3000/about');

    cy.get('[data-testid="offline-message"]').should('be.visible');
    cy.get('[data-testid="offline-message"]').should('contain', 'Connection Lost');
  });

  it('should hide offline message when connection is restored', () => {
    cy.window().then((win) => {
      win.dispatchEvent(new Event('offline'));
    });

    cy.get('[data-testid="offline-message"]').should('be.visible');

    cy.window().then((win) => {
      win.dispatchEvent(new Event('online'));
    });

    cy.get('[data-testid="offline-message"]').should('not.exist');
  });

  it('should display appropriate styling for offline message', () => {
    cy.window().then((win) => {
      win.dispatchEvent(new Event('offline'));
    });

    cy.get('[data-testid="offline-message"]').should('be.visible');
    cy.get('[data-testid="offline-message"]').should('have.css', 'display').and('not.equal', 'none');
    cy.get('[data-testid="offline-message"]').should('have.css', 'background-color');
    cy.get('[data-testid="offline-icon"]').should('exist');
  });
});
